const searchWorkshops = `-- name: SearchWorkshops :many
SELECT w.id, w.name, w.offers_home_service, w.home_service_fee_cents, w.currency, w.rating_sum, w.rating_count, a.lat, a.lng, a.line,
       ST_Distance(a.geom, ST_SetSRID(ST_MakePoint($1::float8, $2::float8), 4326)::geography)::float8 AS distance_m,
       EXISTS (SELECT 1 FROM workshop_favorites f WHERE f.workshop_id = w.id AND f.customer_id = $3) AS is_favorite,
       COALESCE((SELECT m.object_key FROM workshop_photos p JOIN media_uploads m ON m.id = p.upload_id
                 WHERE p.workshop_id = w.id ORDER BY p.position LIMIT 1), '')::text AS cover_key
FROM workshops w JOIN addresses a ON a.id = w.address_id
WHERE w.is_active
  AND ($4::text = '' OR w.name ILIKE '%' || $4::text || '%')
  AND ($5::text = '' OR EXISTS (
        SELECT 1 FROM workshop_services s JOIN catalog_items c ON c.id = s.category_id
        WHERE s.workshop_id = w.id AND s.is_active AND c.code = $5::text))
  AND (NOT $6::boolean OR EXISTS (SELECT 1 FROM workshop_favorites f WHERE f.workshop_id = w.id AND f.customer_id = $3))
  AND (NOT $7::boolean OR w.offers_home_service)
  AND ($8::bigint = 0 OR (w.rating_count > 0 AND w.rating_sum * 100 >= $8::bigint * w.rating_count))
  AND ($9::float8 = 0 OR ST_DWithin(a.geom, ST_SetSRID(ST_MakePoint($1::float8, $2::float8), 4326)::geography, $9::float8))
ORDER BY CASE WHEN $10::boolean THEN (w.rating_sum::float8 / GREATEST(w.rating_count, 1)) END DESC NULLS LAST, distance_m, w.id
LIMIT $12 OFFSET $11
`

type SearchWorkshopsParams struct {
	Lng           float64   `json:"lng"`
	Lat           float64   `json:"lat"`
	CustomerID    uuid.UUID `json:"customer_id"`
	Search        string    `json:"search"`
	Category      string    `json:"category"`
	OnlyFavorites bool      `json:"only_favorites"`
	OnlyHome      bool      `json:"only_home"`
	MinRatingBps  int64     `json:"min_rating_bps"`
	MaxDistanceM  float64   `json:"max_distance_m"`
	ByRating      bool      `json:"by_rating"`
	PageOffset    int32     `json:"page_offset"`
	PageLimit     int32     `json:"page_limit"`
}

type SearchWorkshopsRow struct {
	ID                  uuid.UUID `json:"id"`
	Name                string    `json:"name"`
	OffersHomeService   bool      `json:"offers_home_service"`
	HomeServiceFeeCents int64     `json:"home_service_fee_cents"`
	Currency            string    `json:"currency"`
	RatingSum           int64     `json:"rating_sum"`
	RatingCount         int32     `json:"rating_count"`
	Lat                 float64   `json:"lat"`
	Lng                 float64   `json:"lng"`
	Line                string    `json:"line"`
	DistanceM           float64   `json:"distance_m"`
	IsFavorite          bool      `json:"is_favorite"`
	CoverKey            string    `json:"cover_key"`
}

func (q *Queries) SearchWorkshops(ctx context.Context, arg SearchWorkshopsParams) ([]SearchWorkshopsRow, error) {
	rows, err := q.db.Query(ctx, searchWorkshops,
		arg.Lng,
		arg.Lat,
		arg.CustomerID,
		arg.Search,
		arg.Category,
		arg.OnlyFavorites,
		arg.OnlyHome,
		arg.MinRatingBps,
		arg.MaxDistanceM,
		arg.ByRating,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchWorkshopsRow{}
	for rows.Next() {
		var i SearchWorkshopsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.OffersHomeService,
			&i.HomeServiceFeeCents,
			&i.Currency,
			&i.RatingSum,
			&i.RatingCount,
			&i.Lat,
			&i.Lng,
			&i.Line,
			&i.DistanceM,
			&i.IsFavorite,
			&i.CoverKey,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

